-- Replace the placeholder game rows from the seed with the real, published games.
--   Mini Old Games  https://github.com/NOMBER/Mini-Old-Games  (plugin id good-old-games)
--   HELLVAULT       https://github.com/NOMBER/HELLVAULT       (plugin id vault-shards)
-- The old rows ('mini-games', 'vault-shards') were never used by a real game build, so they are removed
-- (this also frees plugin_id 'vault-shards'). Any test library/stats rows for them go away with them.
-- Safe to run more than once.

delete from public.games where id in ('mini-games', 'vault-shards');

-- Mini Old Games (mini-old-games) manifest v1
insert into public.games (id, plugin_id, name, description, repo_url, status)
values ('mini-old-games', 'good-old-games', 'Mini Old Games', '12 classic mini-games right inside your vault: Snake, Tetris, 2048, Minesweeper, Flappy Bird, Breakout, Pong, Whack-a-Mole, Memory, Space Invaders, Sudoku and Simon. Desktop and mobile.', 'https://github.com/NOMBER/Mini-Old-Games', 'listed')
on conflict (id) do update set plugin_id = excluded.plugin_id, name = excluded.name,
  description = coalesce(excluded.description, public.games.description),
  repo_url = coalesce(excluded.repo_url, public.games.repo_url), status = excluded.status;
